requirements.referenceSolution:
class Cache {
    private final Map<String,Integer> m = new ConcurrentHashMap<>();
    int getOrCompute(String k, java.util.function.Supplier<Integer> f) {
        return m.computeIfAbsent(k, x -> f.get());
    }
}

